            archetypeSignatureTagline: 'ローマ数字の部、番号付きの章、セクション区切り。',
            blurbSubmission: '6×9 ページ、サンセリフ体、行間 1.5、独立したシーンオープナーによるシンプルな閲覧用ドラフト。読者に合わせてレイアウトとタイポグラフィをカスタマイズできます。',
            blurbReadingDraft: 'ベータリーダーや校正者向けの洗練された閲覧用ドラフト。最終的なデザインを決めなくても、完成した本のような仕上がりになります。現代的なセリフ体の本文、ゆとりのある行間、そして現代の商業フィクションになじみのある控えめな構成。',
            blurbLiterary: '洗練された出版志向のスタイル — プロが組版した単行本のような雰囲気。ランニングヘッド、構造化された章の見せ方、より強い視覚的リズムが、控えめで読みやすさを保ちながら、より没入感のある読書体験を生み出します。',
            blurbStructured: '建築的で文学的。意図的なペース配分、構造的な余白、幕のオープナー、エピグラフ、特徴的なシーンの見せ方が活きる野心的なフィクションのために設計されています。ブティック系の文芸書や、ミッドセンチュリーの印刷デザインの伝統にある丁寧な職人技を想起させます。',
            notePage: 'ページの寸法と余白は、多くの著者が思う以上に読書体験を左右します。詰めたレイアウトは密度とテンポを高め、広い余白は視覚的なゆとりと文学的な雰囲気を生みます。一般的な単行本のフィクションは、読みやすさと効率的なページ数のバランスを取っています。',
            noteBody: '本文のタイポグラフィは、長文を読む際の快適さを左右します。セリフ体が印刷されたフィクションで主流であり続けているのは、文字の詰まったページでも自然に視線を導くからです。行間はペースに微妙に影響します：詰めた行間は速く切迫した印象を与え、広い行間は読者の速度を落として内省を促します。',
            noteHeaders: 'ランニングヘッダーは長い作品で読者が現在位置を把握するのに役立ち、完成した印刷版では一般的です。下書き原稿では省略されることが多い一方、洗練された単行本や文芸書のレイアウトでは、本文の邪魔をせずに構造を補強する控えめなヘッダーがよく使われます。',
            noteFolio: 'ページ番号は、原稿の中で読者の位置をさりげなく示します。従来の原稿ではノンブルを下部中央に置くことが多く、出版されたフィクションでは、より洗練された見せ方としてランニングヘッダーに組み込むことがよくあります。',
            noteParts: '部のページは物語の大きな流れを区切り、幕や物語の段階の間に構造的なゆとりを生みます。文芸作品や大規模な商業フィクションでは、テーマの転換や長い物語の勢いを強めるために、専用の部オープナー、ローマ数字、エピグラフがよく使われます。',
            noteChapters: '章の見せ方は物語のリズムを形づくります。最小限の章ページはテンポを目立たせず速く保ち、大きなオープナーは間、強調、期待を生みます。共通の章タイトルやオープナーの余白は、トーンやジャンルへの期待をさりげなく補強できます。',
            noteScenes: 'シーン区切りはミクロなレベルで勢いを制御します。目立たない切り替えはスピードと連続性を生み、専用のシーンオープナーは各シーケンスに感情的・構造的な重みを与えます。番号、タイトル、装飾罫は、複雑な物語の中で読者が位置を把握する助けになります。',
            noteEpigraph: 'エピグラフは、本文が始まる前にそのセクションの感情的・テーマ的なレンズを設定します。強調のために控えめに使う小説もあれば、文芸作品や構造的なフィクションでは、幕、章、キャラクターの弧をまたいで共鳴を生むために繰り返しエピグラフを使うこともあります。',
